// Monitor Inteligente de Fatiga Publicitaria y Diagnóstico de App
const data = items[0].json.body || items[0].json;
const frequency = parseFloat(data.frequency || 1.0);
const ctr = parseFloat(data.ctr || 2.5);
const spendUSD = parseFloat(data.spendUSD || 0);
const roas = parseFloat(data.roas || 4.5);

let fatigueAlert = false;
let actionRequired = 'Normal - Campañas con buen rendimiento y sin saturación.';

if (frequency >= 2.8 || ctr < 1.5) {
  fatigueAlert = true;
  actionRequired = 'ALERTA DE FATIGA: Frecuencia elevada o caída de CTR. Se ordena pausar adsets saturados y activar nuevo ángulo psicológico (Creative Refresh).';
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    source: 'consumer-behavior-diagnostician',
    fatigueAlert,
    frequency,
    ctr,
    spendUSD,
    roas,
    actionRequired,
    notifyGM: fatigueAlert || roas < 4.0,
    title: fatigueAlert ? '⚠️ ALERTA: Fatiga Publicitaria Detectada en Meta Ads' : '✅ Diagnóstico Saludable de Audiencia & App'
  }
}];

// Consolidador Financiero y Plan de Acción del Gerente General (COO)
