const dateStr = new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const mrrUSD = input.mrrUSD || 14850;
const revenueTodayUSD = input.revenueTodayUSD || 1280;
const adSpendUSD = input.adSpendUSD || 180;
const netProfitTodayUSD = revenueTodayUSD - adSpendUSD;
const ltvCacRatio = input.ltvCacRatio || 5.2;

const actionPlan = input.actionPlan || [
  'Escalar conjunto ganador de Lookalikes CFOs en Meta Ads (+20% presupuesto)',
  'Refrescar creativos de Instagram Reels con enfoque en privacidad en RAM volátil',
  'Sesión de seguimiento fiduciario con 3 despachos corporativos en proceso de cierre de $599/año'
];

